    expanded_srcs = []
    for src in srcs:
        matches = glob.glob(src)
        if matches:
            expanded_srcs.extend(matches)
        else:
            expanded_srcs.append(src)
    srcs = expanded_srcs

def backup_file(filepath):
    if not os.path.exists(filepath):
        return
    if args.backup == 'none' or args.backup == 'off':
        return

    if args.backup == 'numbered':
        num = 1
        while True:
            bname = f"{filepath}.~{num}~"
            if not os.path.exists(bname):
                shutil.copy2(filepath, bname)
                break
            num += 1
    elif args.backup == 'auto':
        # only create numbered if previous backup exists, else simple
        # but xcp says simple backups are not supported, "only numbered"
        # wait, README: "cp 'simple' backups are not supported, only numbered. 'auto' will only create a numbered backup if a previous backups exists."
        has_numbered = False
        num = 1
        while os.path.exists(f"{filepath}.~{num}~"):
            has_numbered = True
            num += 1
        if has_numbered:
            bname = f"{filepath}.~{num}~"
            shutil.copy2(filepath, bname)

