    if not args.no_perms:
        shutil.copymode(src, dst, follow_symlinks=args.dereference)
    if not args.no_timestamps:
        shutil.copystat(src, dst, follow_symlinks=args.dereference)
    if args.fsync:
        with open(dst, 'a') as f:
            os.fsync(f.fileno())

