    if not os.path.exists(dst_dir):
        os.makedirs(dst_dir, exist_ok=True)
        if not args.no_perms:
            shutil.copymode(src, dst_dir, follow_symlinks=args.dereference)
        if not args.no_timestamps:
            shutil.copystat(src, dst_dir, follow_symlinks=args.dereference)

