            if os.path.exists(d) and args.no_clobber:
                continue
            if os.path.exists(d):
                backup_file(d)
                os.remove(d)
            target = os.readlink(s)
            os.symlink(target, d)
        elif os.path.isdir(s):
            if args.recursive:
                process_dir(s, d)
        else:
            tasks.append((s, d))

