        if args.no_target_dir:
            process_dir(src, dest)
        else:
            # if multiple srcs and dest is an existing directory, it goes inside
            # if one src and dest doesn't exist, it renames? 
            # cp -r dir1 dir2 (where dir2 does not exist) -> creates dir2 with contents of dir1
            # cp -r dir1 dir2 (where dir2 exists) -> creates dir2/dir1 with contents
            if os.path.exists(dest) and os.path.isdir(dest):
                d = os.path.join(dest, base_src)
                process_dir(src, d)
            else:
                process_dir(src, dest)
    else:
        # file
        if os.path.isdir(dest) and not args.no_target_dir:
            d = os.path.join(dest, os.path.basename(src))
        else:
            d = dest
        tasks.append((src, d))

if tasks:
    with ThreadPoolExecutor(max_workers=args.workers) as executor:
        futures = [executor.submit(copy_file, t[0], t[1]) for t in tasks]
        for f in futures:
            f.result()
