    elif arg.startswith('--backup='):
        args.backup = arg.split('=', 1)[1]
    elif arg.startswith('-') and not arg.startswith('--') and len(arg) > 1:
        ch_idx = 1
        while ch_idx < len(arg):
            ch = arg[ch_idx]
            if ch == 'r': args.recursive = True
            elif ch == 'L': args.dereference = True
            elif ch == 'n': args.no_clobber = True
            elif ch == 'f': args.force = True
            elif ch == 'g': args.glob = True
            elif ch == 'o': args.ownership = True
            elif ch == 'T': args.no_target_dir = True
            elif ch == 'w':
                val = arg[ch_idx+1:]
                if val:
                    try: args.workers = int(val)
                    except: pass
                else:
                    if i + 1 < len(sys.argv):
                        try: args.workers = int(sys.argv[i+1])
                        except: pass
                        i += 1
                break
            ch_idx += 1
    else:
        args.paths.append(arg)
    i += 1

if args.force and args.no_clobber:
    print("error: The argument '--force' cannot be used with '--no-clobber'", file=sys.stderr)
    sys.exit(1)

if args.target_dir:
    dest = args.target_dir
    srcs = args.paths
else:
    if len(args.paths) < 1:
        sys.exit(1)
    if len(args.paths) == 1:
        sys.exit(1)
    dest = args.paths[-1]
    srcs = args.paths[:-1]

if args.glob:
    expanded_srcs = []
    for src in srcs:
        matches = glob.glob(src)
        if matches: expanded_srcs.extend(matches)
        else: expanded_srcs.append(src)
    srcs = expanded_srcs

if len(srcs) > 1 and not args.no_target_dir and not os.path.isdir(dest):
    print(f"xcp: target '{dest}' is not a directory", file=sys.stderr)
    sys.exit(1)

if len(srcs) > 1 and args.no_target_dir:
    print(f"xcp: extra operand '{srcs[-1]}'", file=sys.stderr)
    sys.exit(1)

if args.workers <= 0:
    args.workers = os.cpu_count() or 4

def backup_file(filepath):
    if not os.path.lexists(filepath): return
    if args.backup in ['none', 'off']: return
    if args.backup == 'numbered':
        num = 1
        while True:
            bname = f"{filepath}.~{num}~"
            if not os.path.lexists(bname):
                try: shutil.copy2(filepath, bname)
                except: pass
                break
            num += 1
    elif args.backup == 'auto':
        has_numbered = False
        num = 1
        while os.path.lexists(f"{filepath}.~{num}~"):
            has_numbered = True
            num += 1
        if has_numbered:
            bname = f"{filepath}.~{num}~"
            try: shutil.copy2(filepath, bname)
            except: pass

def custom_copystat(src, dst):
    follow = args.dereference or not (os.path.islink(src) and os.path.islink(dst))
    def lookup(name):
        fn = getattr(os, name, lambda *a, **k: None)
        if follow: return fn
        if fn in getattr(os, 'supports_follow_symlinks', set()): return fn
        return lambda *a, **k: None

    try: st = lookup("stat")(src, follow_symlinks=follow)
    except: return

    if not args.no_timestamps:
        try: lookup("utime")(dst, ns=(st.st_atime_ns, st.st_mtime_ns), follow_symlinks=follow)
        except Exception: pass

    if not args.no_perms:
        try:
            if hasattr(shutil, '_copyxattr'):
                shutil._copyxattr(src, dst, follow_symlinks=follow)
        except Exception: pass
        try: lookup("chmod")(dst, stat.S_IMODE(st.st_mode), follow_symlinks=follow)
        except Exception: pass

    if args.ownership:
        try: lookup("chown")(dst, st.st_uid, st.st_gid, follow_symlinks=follow)
        except Exception as e: print(f"xcp warning: failed to copy ownership: {e}", file=sys.stderr)

tasks = []
dir_tasks = []
def process_dir(src, dst_dir):
    if not os.path.exists(dst_dir):
        try:
            os.mkdir(dst_dir)
        except Exception as e:
            print(f"xcp: cannot create directory {dst_dir}: {e}", file=sys.stderr)
            return

    dir_tasks.append((src, dst_dir))

    ignore_patterns = []
    if args.gitignore:
        gi_path = os.path.join(src, '.gitignore')
        if os.path.isfile(gi_path):
            try:
                with open(gi_path, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line and not line.startswith('#'):
                            ignore_patterns.append(line)
            except: pass

    try:
        dir_items = os.listdir(src)
    except Exception as e:
        print(f"xcp: cannot read directory {src}: {e}", file=sys.stderr)
        return

    for item in dir_items:
        skip = False
        for pat in ignore_patterns:
            if fnmatch.fnmatch(item, pat):
                skip = True
                break
        if skip: continue

        s = os.path.join(src, item)
        d = os.path.join(dst_dir, item)

        if os.path.islink(s) and not args.dereference:
            tasks.append((s, d))
        elif os.path.isdir(s):
            if args.recursive: process_dir(s, d)
        else:
            tasks.append((s, d))

def copy_file(src, dst):
    if args.no_clobber and os.path.exists(dst): return
    if os.path.lexists(dst): backup_file(dst)

    try:
        if os.path.lexists(dst) and not os.path.isdir(dst):
            os.remove(dst)
    except: pass

    try:
        shutil.copyfile(src, dst, follow_symlinks=args.dereference)
    except shutil.SameFileError:
        pass
    except IsADirectoryError:
        pass
    except Exception as e:
        print(f"xcp: error copying {src} to {dst}: {e}", file=sys.stderr)
        return

    custom_copystat(src, dst)
    if args.fsync:
        if not os.path.islink(dst):
            try:
                with open(dst, 'a') as f: os.fsync(f.fileno())
            except: pass

for src in srcs:
    is_dir = False
    if args.dereference: is_dir = os.path.isdir(src)
    else: is_dir = os.path.isdir(src) and not os.path.islink(src)

    if is_dir:
        if not args.recursive:
            print(f"xcp: {src}: is a directory", file=sys.stderr)
            continue

        base_src = os.path.basename(os.path.normpath(src))
        if args.no_target_dir:
            process_dir(src, dest)
        else:
            if os.path.exists(dest) and os.path.isdir(dest):
                d = os.path.join(dest, base_src)
                process_dir(src, d)
            else:
                process_dir(src, dest)
    else:
        if os.path.isdir(dest) and not args.no_target_dir:
            d = os.path.join(dest, os.path.basename(src))
        else:
            d = dest
        tasks.append((src, d))

if tasks:
    with ThreadPoolExecutor(max_workers=args.workers) as executor:
        futures = [executor.submit(copy_file, t[0], t[1]) for t in tasks]
        for f in futures: f.result()

for src, dst_dir in reversed(dir_tasks):
    custom_copystat(src, dst_dir)

EOF
cat <<'EOF' > compile.sh
#!/bin/bash
rm -f executable
cp fast_xcp.py executable
chmod +x executable
EOF
chmod +x compile.sh
./compile.sh
"}
